package com.hbm.missile.launchpad.standard;
import api.hbm.item.IDesignatorItem;import com.hbm.fluid.FluidContainerRegistry;import com.hbm.item.battery.*;import com.hbm.recipe.generic.GenericOutputSlot;import com.hbm.registry.HbmContent;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Original seven-slot container and priority-ordered shift-click classification. */
public final class StandardLaunchPadMenu extends AbstractContainerMenu {
 public final StandardLaunchPadBlockEntity machine;private final Container inventory;private final BlockPos pos;public StandardLaunchPadMenu(int id,Inventory player,RegistryFriendlyByteBuf buffer){this(id,player,buffer.readBlockPos());}private StandardLaunchPadMenu(int id,Inventory player,BlockPos pos){this(id,player,player.player.level().getBlockEntity(pos) instanceof StandardLaunchPadBlockEntity be?be:new SimpleContainer(7),pos);}public StandardLaunchPadMenu(int id,Inventory player,Container container,BlockPos pos){super(StandardLaunchPadContent.MENU.get(),id);checkContainerSize(container,7);inventory=container;machine=container instanceof StandardLaunchPadBlockEntity be?be:null;this.pos=pos;addSlot(new Slot(container,0,26,36));addSlot(new Slot(container,1,26,72));addSlot(new Slot(container,2,107,90));addSlot(new Slot(container,3,125,90));addSlot(new GenericOutputSlot(player.player,container,4,125,108));addSlot(new Slot(container,5,143,90));addSlot(new GenericOutputSlot(player.player,container,6,143,108));for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlot(new Slot(player,9+row*9+col,8+col*18,154+row*18));for(int col=0;col<9;col++)addSlot(new Slot(player,col,8+col*18,212));}public BlockPos position(){return pos;}@Override public boolean stillValid(Player player){return inventory.stillValid(player);}
 @Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size()||machine==null)return ItemStack.EMPTY;var slot=getSlot(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var copy=stack.copy();if(index<=6){if(!moveItemStackTo(stack,7,slots.size(),true))return ItemStack.EMPTY;}else{int target;if(stack.getItem() instanceof HbmBattery||stack.getItem() instanceof CreativeBatteryItem)target=2;else if(machine.isMissileValid(stack))target=0;else if(stack.is(HbmContent.item("fluid_barrel_infinite"))){if(!moveItemStackTo(stack,3,4,false)&&!moveItemStackTo(stack,5,6,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return copy;}else if(FluidContainerRegistry.getFluidContent(stack,machine.tanks[0].getTankType())>0)target=3;else if(FluidContainerRegistry.getFluidContent(stack,machine.tanks[1].getTankType())>0)target=5;else if(stack.getItem() instanceof IDesignatorItem)target=1;else return ItemStack.EMPTY;if(!moveItemStackTo(stack,target,target+1,false))return ItemStack.EMPTY;}if(stack.isEmpty())slot.setByPlayer(ItemStack.EMPTY);else slot.setChanged();return copy;}
}
